import type { Metadata } from "next";
import { redirect } from "next/navigation";
import { VendorWorkspaceHeader } from "../../../components/VendorWorkspaceHeader";
import { getVendorSession } from "../../../lib/vendor-session";
import { vendorAnalyticsWorkspace } from "../../../lib/vendor-backoffice-service";
export const metadata: Metadata = { title: "Vendor Analytics", robots: { index: false, follow: false } };
export default async function VendorAnalyticsPage() { const principal = await getVendorSession(); if (!principal) redirect("/vendor/login"); const report = await vendorAnalyticsWorkspace(principal); const rows=[['Qualified impressions',report.qualifiedImpressions],['Product views',report.productViews],['Cart adds',report.cartAdds],['Attributed orders',report.attributedOrders],['Attributed units',report.attributedUnits],['Attributed retail sales',report.attributedRetailSales],['Advice starts',report.adviceStarts],['Appointments',report.appointmentsBooked],['Ask Local requests',report.counterofferRequests],['Private offers',report.counterofferOffers],['Accepted offers',report.counterofferAccepted]]; return <main className="vendor-app"><VendorWorkspaceHeader /><section className="shell vendor-hero vendor-hero-compact"><div><div className="eyebrow">Own performance only · last 30 days</div><h1>Analytics</h1><p className="lead">Supplier-scoped aggregates χωρίς competitor, customer-level ή raw marketplace data. Τα analytics δεν επηρεάζουν Fair Vendor Exposure.</p></div></section><section className="shell vendor-section"><div className="vendor-kpis vendor-kpis-wide">{rows.map(([label,value])=><div key={String(label)}><span>{label}</span><strong>{value}</strong></div>)}</div></section></main>; }
